std::string decode_data(std::ifstream &infile, std::shared_ptr<Node> &root, int encoded_length) {
    std::string decoded_text;
    decoded_text.reserve(encoded_length / 2); // rough estimate

    std::shared_ptr<Node> current = root;
    char byte;
    int bits_processed = 0;

    while (bits_processed < encoded_length && infile.read(&byte, 1)) {
        // Process each bit in the byte, from MSB to LSB
        for (int bit_pos = 7; bit_pos >= 0 && bits_processed < encoded_length; bit_pos--) {
            bool bit = (byte >> bit_pos) & 1;

            if (bit) {
                current = current->right;
            } else {
                current = current->left;
            }

            // Check if we reached a leaf node
            if (current && !current->left && !current->right) {
                decoded_text.push_back(current->character);
                current = root; // Reset to root for next sequence
            }
        }
        bits_processed += 8;
    }

    // Handle case where we might have partially read the last byte
    // (if encoded_length is not a multiple of 8, we may have read extra bits)
    // But the loop condition ensures we only process exactly encoded_length bits

    return decoded_text;
}

